/**
 * Virtual sports mock data.
 * Virtual games run every few minutes — each has a fixed "next kick-off" time.
 * Results are generated by RNG on the backend in a real implementation.
 */

export interface VirtualGame {
  id: string;
  category: string;         // "virtual_football" | "virtual_basketball" | etc.
  categoryLabel: string;
  icon: string;
  description: string;      // e.g. "Virtual Premier League — Round 14"
  kickoffIn: number;        // seconds until next game starts
  duration: number;         // seconds the game runs
  outcomes: Array<{
    name: string;
    oddsBps: number;
    avgDecimalOdds: number;
  }>;
}

function secsFromNow(s: number): number {
  return s; // just return seconds — client uses this as countdown
}

