// ── Aviator / Crash game state ───────────────────────────────────────────────

export interface AviatorRound {
  roundId: number;
  status: 'waiting' | 'flying' | 'crashed';
  multiplier: number;       // current multiplier e.g. 1.00 → 4.32
  crashPoint: number | null; // null until crashed
  startedAt: string | null;
  history: number[];        // last 10 crash points
}

let _roundId = 1001;
let _history = [14.32, 1.05, 3.88, 2.11, 1.42, 9.77, 1.01, 6.54, 2.90, 1.23];

export function getAviatorState(): AviatorRound {
  return {
    roundId: _roundId,
    status: 'waiting',
    multiplier: 1.00,
    crashPoint: null,
    startedAt: null,
    history: [..._history],
  };
}

export function recordCrash(crashPoint: number): void {
  _roundId++;
  _history = [crashPoint, ..._history].slice(0, 10);
}
